import pandas as pd

# Load all available experiment data and check columns
for exp in [1, 5, 6, 7, 9]:
    try:
        df = pd.read_csv(f"experiment_{exp}_csv")
        print(f"\n=== Experiment {exp} ===")
        print(f"Columns: {list(df.columns)}")
        print(f"Shape: {df.shape}")
        # Check for any intervention columns
        non_measurement_cols = [c for c in df.columns if c not in ['ProductTiter', 'DissolvedOxygen', 'ViableCellDensity', 'pH', 'Temperature']]
        if non_measurement_cols:
            print(f"Intervention/control columns: {non_measurement_cols}")
            print(df[non_measurement_cols].describe())
        if 'ProductTiter' in df.columns:
            print(f"Mean Titer: {df['ProductTiter'].mean():.2f}")
        if 'ViableCellDensity' in df.columns:
            print(f"Mean VCD: {df['ViableCellDensity'].mean():.2f}")
    except Exception as e:
        print(f"Error with exp {exp}: {e}")
